SELECT customer_id, SUM(amount)
FROM orders
GROUP BY customer_id;

SELECT e.name AS employee, m.name AS manager
FROM employees e
LEFT JOIN employees m ON e.manager_id = m.id;

-- 1. lặp lại biểu thức
SELECT price * qty AS total FROM order_items WHERE price * qty > 100;

-- 2. bọc bằng subquery / CTE
SELECT * FROM (
  SELECT price * qty AS total FROM order_items
) t WHERE t.total > 100;

-- 3. LATERAL (PostgreSQL) để tính một lần
SELECT c.total FROM order_items i
CROSS JOIN LATERAL (SELECT i.price * i.qty AS total) c
WHERE c.total > 100;

-- nhieu bai cung created_at -> thu tu khong on dinh
SELECT * FROM posts ORDER BY created_at DESC LIMIT 20 OFFSET 20;

-- sua: them tie-breaker duy nhat
SELECT * FROM posts ORDER BY created_at DESC, id DESC LIMIT 20 OFFSET 20;

-- non-sargable: forces a full scan
SELECT * FROM orders WHERE DATE(created_at) = '2026-01-01';

-- sargable: half-open range, index on created_at is usable
SELECT * FROM orders
WHERE created_at >= '2026-01-01'
  AND created_at <  '2026-01-02';

BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1;
UPDATE accounts SET balance = balance + 100 WHERE id = 2;
COMMIT;

create table products (
  id bigserial primary key,
  name text not null,
  description text
);

create table variants (
  id         bigserial primary key,
  product_id bigint not null references products(id),
  sku        text   not null unique,
  price      numeric(12,2) not null,
  attributes jsonb not null default '{}'  -- {"size":"M","color":"black"}
);

create table cart_items (
  cart_id    bigint not null references carts(id),
  variant_id bigint not null references variants(id),
  quantity   int not null check (quantity > 0),
  primary key (cart_id, variant_id)
);

WITH recent_orders AS (
  SELECT * FROM orders WHERE created_at > now() - interval '7 days'
)
SELECT customer_id, count(*) FROM recent_orders GROUP BY customer_id;

SELECT e.* FROM employees e
  WHERE e.salary > (
    SELECT AVG(salary) FROM employees
    WHERE dept_id = e.dept_id   -- e.dept_id từ truy vấn ngoài
  );

-- Cách 1: subquery — trả NULL nếu không có (đúng yêu cầu đề)
SELECT MAX(salary) AS second_highest
FROM employees
WHERE salary < (SELECT MAX(salary) FROM employees);

-- Cách 2: DENSE_RANK — tổng quát hóa cho "cao thứ N"
SELECT salary FROM (
  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS rnk
  FROM employees
) t WHERE rnk = 2;

SELECT * FROM (
  SELECT e.*, DENSE_RANK() OVER (
    PARTITION BY dept_id ORDER BY salary DESC
  ) AS rnk
  FROM employees e
) t WHERE rnk <= 3;

SELECT c.id FROM customers c
WHERE NOT EXISTS (
  SELECT 1 FROM orders o WHERE o.customer_id = c.id
);

-- N+1: 1 + 100 round-trips
SELECT * FROM posts LIMIT 100;
SELECT * FROM users WHERE id = ?; -- repeated for each post
-- Fix: batch into one query
SELECT * FROM users WHERE id IN (1, 2, ...);

-- Thay vì:
SELECT * FROM orders WHERE user_id = 42;
-- Chỉ lấy cột cần (mở đường index-only scan, ổn định trước đổi schema):
SELECT id, total, created_at FROM orders WHERE user_id = 42;

CREATE MATERIALIZED VIEW daily_sales AS
SELECT date, SUM(amount) FROM orders GROUP BY date;

REFRESH MATERIALIZED VIEW daily_sales;

-- 1. NOT EXISTS: an toan voi NULL, thuong toi uu tot nhat
SELECT * FROM customers c
WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);

-- 2. LEFT JOIN ... IS NULL (anti-join thu cong)
SELECT c.* FROM customers c
LEFT JOIN orders o ON o.customer_id = c.id
WHERE o.customer_id IS NULL;

-- 3. loc NULL truoc khi dua vao NOT IN
WHERE id NOT IN (SELECT customer_id FROM orders WHERE customer_id IS NOT NULL);

-- phone is VARCHAR, 0901234567 is a number
-- MySQL converts every phone value to a number: index unusable
SELECT * FROM users WHERE phone = 0901234567;

-- correct: compare string to string
SELECT * FROM users WHERE phone = '0901234567';

-- does not enforce what you expect: NULL never conflicts with NULL,
-- so many soft-deleted rows can share the same email
CREATE UNIQUE INDEX uq_users_email ON users (email, deleted_at);

-- reliable alternative: unique only among live rows
CREATE UNIQUE INDEX uq_users_email_live ON users (email)
WHERE deleted_at IS NULL;

